using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int64> A(N);
    for (int i = 0; i < N; i++) cin >> A[i];

    vector<int64> pref(N + 1, 0);
    for (int i = 0; i < N; i++) pref[i + 1] = pref[i] + A[i];

    auto sum = [&](int l, int r) -> int64 {
        return pref[r] - pref[l];
    };

    int64 ans = 1e18;

    // Try middle cut positions: j between i and k
    int j = 0, k = 1;
    for (int i = 1; i < N - 2; i++) {
        // Adjust j so that |sum(0,j) - sum(j,i)| is minimized
        while (j + 1 < i && sum(0, j + 1) < sum(j + 1, i)) j++;
        // Adjust k so that |sum(i,k) - sum(k,N)| is minimized
        while (k + 1 < N && sum(i, k + 1) < sum(k + 1, N)) k++;

        // Try combinations near j and k
        for (int dj = -1; dj <= 1; dj++) {
            for (int dk = -1; dk <= 1; dk++) {
                int jj = j + dj, kk = k + dk;
                if (jj >= 1 && jj < i && kk > i && kk < N) {
                    int64 P = sum(0, jj);
                    int64 Q = sum(jj, i);
                    int64 R = sum(i, kk);
                    int64 S = sum(kk, N);
                    int64 mx = max({P, Q, R, S});
                    int64 mn = min({P, Q, R, S});
                    ans = min(ans, mx - mn);
                }
            }
        }
    }

    cout << ans << "\n";
    return 0;
}

