using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> A(N), pref(N + 1, 0);
    for (int i = 0; i < N; ++i) {
        cin >> A[i];
        pref[i + 1] = pref[i] + A[i];
    }

    long long ans = (1LL << 62);

    int l = 1;      // first cut in [1, m-1]
    int r = 3;      // third cut in [m+1, N-1]

    for (int m = 2; m <= N - 2; ++m) {
        // Optimize left cut for [0, m)
        while (l + 1 < m) {
            long long p1 = pref[l];
            long long q1 = pref[m] - pref[l];
            long long p2 = pref[l + 1];
            long long q2 = pref[m] - pref[l + 1];
            if (llabs(p2 - q2) <= llabs(p1 - q1)) l++;
            else break;
        }

        // Ensure r is valid for current m
        if (r < m + 1) r = m + 1;

        // Optimize right cut for [m, N)
        while (r + 1 < N) {
            long long r1 = pref[r] - pref[m];
            long long s1 = pref[N] - pref[r];
            long long r2 = pref[r + 1] - pref[m];
            long long s2 = pref[N] - pref[r + 1];
            if (llabs(r2 - s2) <= llabs(r1 - s1)) r++;
            else break;
        }

        long long P = pref[l];
        long long Q = pref[m] - pref[l];
        long long R = pref[r] - pref[m];
        long long S = pref[N] - pref[r];

        long long mx = max(max(P, Q), max(R, S));
        long long mn = min(min(P, Q), min(R, S));
        ans = min(ans, mx - mn);
    }

    cout << ans << '\n';
    return 0;
}

