#define min(a, b) ((a) < (b) ? (a) : (b))
#define max(a, b) ((a) > (b) ? (a) : (b))
#define ll long long

ll prefix[200005];
int n;

ll sum(int l, int r) {
    return prefix[r] - prefix[l];
}

ll absll(ll x) {
    return x < 0 ? -x : x;
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        scanf("%lld", &prefix[i]);
        prefix[i] += prefix[i-1];
    }

    ll ans = 1e18;

    int l = 1, r = 3;
    for (int mid = 2; mid <= n-2; mid++) {
        // adjust left cut to balance sums of B and C
        while (l+1 < mid && absll(sum(0, l+1) - sum(l+1, mid)) < absll(sum(0, l) - sum(l, mid)))
            l++;
        // adjust right cut to balance sums of D and E
        while (r+1 < n && absll(sum(mid, r+1) - sum(r+1, n)) < absll(sum(mid, r) - sum(r, n)))
            r++;

        ll p = sum(0, l);
        ll q = sum(l, mid);
        ll rsum = sum(mid, r);
        ll s = sum(r, n);

        ll mn = p;
        if (q < mn) mn = q;
        if (rsum < mn) mn = rsum;
        if (s < mn) mn = s;

        ll mx = p;
        if (q > mx) mx = q;
        if (rsum > mx) mx = rsum;
        if (s > mx) mx = s;

        ll diff = mx - mn;
        if (diff < ans) ans = diff;
    }

    printf("%lld\n", ans);
    return 0;
}

