typedef long long ll;

static ll llabs2(ll x) { return x >= 0 ? x : -x; }

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *A = (ll *)malloc(sizeof(ll) * N);
    ll *S = (ll *)malloc(sizeof(ll) * (N + 1));
    for (int i = 0; i < N; i++) scanf("%lld", &A[i]);

    S[0] = 0;
    for (int i = 0; i < N; i++) S[i + 1] = S[i] + A[i];

    ll ans = LLONG_MAX;

    int l = 1;       // cut for left half [0..i-1]
    int r = 3;       // cut for right half [i..N-1], as prefix index

    for (int i = 2; i <= N - 2; i++) {
        // Optimize left cut l for segment [0, i)
        while (l + 1 < i) {
            ll p1 = S[l];
            ll q1 = S[i] - S[l];
            ll p2 = S[l + 1];
            ll q2 = S[i] - S[l + 1];
            if (llabs2(p2 - q2) <= llabs2(p1 - q1)) l++;
            else break;
        }

        // Ensure r is at least i+1
        if (r < i + 1) r = i + 1;

        // Optimize right cut r for segment [i, N)
        while (r + 1 < N) {
            ll rr1 = S[r] - S[i];
            ll ss1 = S[N] - S[r];
            ll rr2 = S[r + 1] - S[i];
            ll ss2 = S[N] - S[r + 1];
            if (llabs2(rr2 - ss2) <= llabs2(rr1 - ss1)) r++;
            else break;
        }

        ll P = S[l];
        ll Q = S[i] - S[l];
        ll R = S[r] - S[i];
        ll T = S[N] - S[r];

        ll mx = P;
        if (Q > mx) mx = Q;
        if (R > mx) mx = R;
        if (T > mx) mx = T;

        ll mn = P;
        if (Q < mn) mn = Q;
        if (R < mn) mn = R;
        if (T < mn) mn = T;

        if (mx - mn < ans) ans = mx - mn;
    }

    printf("%lld\n", ans);

    free(A);
    free(S);
    return 0;
}

