        int N = Integer.parseInt(br.readLine());
        long[] A = new long[N];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            A[i] = Long.parseLong(st.nextToken());
        }

        long[] pref = new long[N + 1];
        for (int i = 0; i < N; i++) {
            pref[i + 1] = pref[i] + A[i];
        }

        long ans = Long.MAX_VALUE;

        // j is the second cut (after B and before C)
        // i is the first cut (after A and before B)
        // k is the third cut (after D and before E)
        int i = 0, k = 2;
        for (int j = 1; j < N - 1; j++) {
            // adjust i to balance B and C relative to first two parts
            while (i + 1 < j && Math.abs(pref[i + 1] - (pref[j] - pref[i + 1])) 
                        < Math.abs(pref[i] - (pref[j] - pref[i]))) {
                i++;
            }
            // adjust k to balance D and E
            while (k + 1 < N && Math.abs((pref[k + 1] - pref[j]) - (pref[N] - pref[k + 1])) 
                        < Math.abs((pref[k] - pref[j]) - (pref[N] - pref[k]))) {
                k++;
            }

            long P = pref[i];
            long Q = pref[j] - pref[i];
            long R = pref[k] - pref[j];
            long S = pref[N] - pref[k];

            long max = Math.max(Math.max(P, Q), Math.max(R, S));
            long min = Math.min(Math.min(P, Q), Math.min(R, S));
            ans = Math.min(ans, max - min);
        }

        System.out.println(ans);
    }
}

