                long mid=prefix[k]-prefix[i];
                // binary search j in [i+1, k-1]: Q=prefix[j]-prefix[i], R=prefix[k]-prefix[j]
                int lo=i+1,hi=k-1;
                while(lo<hi){
                    int m=(lo+hi)/2;
                    long Q=prefix[m]-prefix[i],R=prefix[k]-prefix[m];
                    if(Q<R) lo=m+1; else hi=m;
                }
                for(int j=Math.max(i+1,lo-1);j<=Math.min(k-1,lo+1);j++){
                    long Q=prefix[j]-prefix[i],R=prefix[k]-prefix[j];
                    long mx=Math.max(Math.max(P,Q),Math.max(R,S));
