import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        long[] a = new long[N];
        for (int i = 0; i < N; i++) a[i] = fs.nextLong();

        long[] prefix = new long[N + 1];
        for (int i = 0; i < N; i++) prefix[i + 1] = prefix[i] + a[i];

        long ans = Long.MAX_VALUE;

        int leftPtr = 1;   // cut between [0..leftPtr-1] and [leftPtr..mid-1]
        int rightPtr = 3;  // cut between [mid..rightPtr-1] and [rightPtr..N-1]

        for (int mid = 2; mid <= N - 2; mid++) {
            // Optimize left cut for [0, mid)
            while (leftPtr + 1 < mid) {
                long p1 = prefix[leftPtr];
                long q1 = prefix[mid] - prefix[leftPtr];
                long diff1 = Math.abs(p1 - q1);

                long p2 = prefix[leftPtr + 1];
                long q2 = prefix[mid] - prefix[leftPtr + 1];
                long diff2 = Math.abs(p2 - q2);

                if (diff2 <= diff1) leftPtr++;
                else break;
            }

            // Ensure rightPtr is valid for current mid
            if (rightPtr < mid + 1) rightPtr = mid + 1;

            // Optimize right cut for [mid, N)
            while (rightPtr + 1 <= N - 1) {
                long r1 = prefix[rightPtr] - prefix[mid];
                long s1 = prefix[N] - prefix[rightPtr];
                long diff1 = Math.abs(r1 - s1);

                long r2 = prefix[rightPtr + 1] - prefix[mid];
                long s2 = prefix[N] - prefix[rightPtr + 1];
                long diff2 = Math.abs(r2 - s2);

                if (diff2 <= diff1) rightPtr++;
                else break;
            }

            // Candidates around optimal left/right cuts
            int[] leftCandidates = {leftPtr, leftPtr + 1};
            int[] rightCandidates = {rightPtr, rightPtr + 1};

            for (int l : leftCandidates) {
                if (!(1 <= l && l < mid)) continue;
                long P = prefix[l];
                long Q = prefix[mid] - prefix[l];

                for (int r : rightCandidates) {
                    if (!(mid < r && r <= N - 1)) continue;
                    long R = prefix[r] - prefix[mid];
                    long S = prefix[N] - prefix[r];

                    long max = Math.max(Math.max(P, Q), Math.max(R, S));
                    long min = Math.min(Math.min(P, Q), Math.min(R, S));
                    ans = Math.min(ans, max - min);
                }
            }
        }

        System.out.println(ans);
    }
}
